function message(s:string){el('message').textContent=s;if(!s.startsWith('В библиотеке:')&&!s.startsWith('Показаны первые'))el('playerNotice').textContent=s}
function status(s:string){el('status').textContent=s}
const fmt=(s:number)=>Number.isFinite(s)?Math.floor(s/60).toString().padStart(2,'0')+':'+Math.floor(s%60).toString().padStart(2,'0'):'--:--';
async function api<T>(path:string,method='GET',body?:BodyInit){const headers:Record<string,string>={};if(method!=='GET')headers['X-RuneAmp-Request']='1';if(typeof body==='string')headers['Content-Type']='application/json';const r=await fetch('/api/'+path,{method,body,headers});if(!r.ok){if((r.status===401||r.status===403)&&identity.role!=='guest'&&!authBusy&&path!=='me')void initIdentity();const x=await r.json().catch(()=>({error:'HTTP '+r.status}));throw Error(x.error??'HTTP '+r.status)}return await r.json() as T}
function pref(){try{localStorage.setItem('runeamp-pref',JSON.stringify({volume,shuffle,repeat,eq}))}catch{}}
function settings(){try{const p=JSON.parse(localStorage.getItem('runeamp-pref')??'{}');if(Number.isFinite(p.volume))volume=Math.max(0,Math.min(1,p.volume));eq=sanitizeEQ(p.eq);shuffle=!!p.shuffle;if(['off','all','one'].includes(p.repeat))repeat=p.repeat}catch{}input('volume').value=String(volume*100);input('shuffle').checked=shuffle;select('repeat').value=repeat}
function changeVolume(){if(nativeEffects)nativeEffects.update(eq,volume);else audio.volume=volume;ay?.setEffects(eq)}
async function activate(){try{if(!nativeContext){nativeContext=new AudioContext();const source=nativeContext.createMediaElementSource(audio);nativeEffects=new AudioEffects(nativeContext);nativeAnalyser=nativeEffects.analyser;source.connect(nativeEffects.input);audio.volume=1;nativeEffects.update(eq,volume,true)}await nativeContext.resume()}catch{}}
function stopPlayback(){recordListening(false);generation++;ay?.dispose();ay=undefined;audio.pause();audio.removeAttribute('src');audio.load();if(objectURL){URL.revokeObjectURL(objectURL);objectURL=''}active=false;paused=false;fallback=false;status('Остановлено')}
function updateNow(){const t=queue[current];el('now').textContent=t?.name??'Выберите композицию';el('format').textContent=t?(t.format==='ts'?'TurboSound · 6ch':t.format.toUpperCase())+' / '+(t.mode==='ay'?'AY-3-8910':t.mode==='module'?'TRACKER':t.mode==='gme'?'CHIP':'AUDIO'):'READY';el('queuecount').textContent=queue.length+' треков';btn('stop').disabled=!active;btn('play').disabled=!queue.length;btn('prev').disabled=!queue.length;btn('next').disabled=!queue.length;el('miniNow').textContent=t?.name??'Музыка не выбрана';updateLike();updateMini()}
async function playAt(i:number,remember=true){if(i<0||i>=queue.length)return;const old=current;stopPlayback();if(remember&&old>=0&&old!==i)history.push(old);current=i;selected=i;listeningStarted=true;const bagIndex=bag.indexOf(i);if(bagIndex>=0){bag[bagIndex]=bag[bag.length-1];bag.pop()}const g=generation,t=queue[i];active=true;noteRecent(t);status('Загрузка…');renderQueue();updateNow();try{
 if(t.mode==='ay'){ayContext??=new AudioContext();await ayContext.resume();if(g!==generation)return;const f=t.file??await fetch('/api/media/'+t.id).then(async r=>{if(!r.ok)throw Error('Файл недоступен');return new File([await r.blob()],t.name)});if(g!==generation)return;ay=new PT3Music(ayContext,s=>{if(g===generation&&!paused)status(s)},()=>{if(g===generation){recordListening(true);failed.clear();advance(true)}},()=>{if(g===generation)onFailure('Ошибка AY-декодера')});ay.setEffects(eq);if(!f)throw Error("Файл недоступен");await ay.load(f);if(g===generation&&paused)ay.setPaused(true)}
 else{await activate();if(g!==generation)return;const url=t.file?(objectURL=URL.createObjectURL(t.file)):'/api/'+(t.mode==='native'?'media/':'stream/')+t.id;audio.src=url;if(!paused)await audio.play();if(g===generation)status(paused?'Пауза':'Воспроизведение')}
 }catch(e){if(g===generation&&!paused)onFailure(String(e instanceof Error?e.message:e))}}
function onFailure(s:string){if(!active)return;const t=queue[current];if(t&&!t.file&&t.mode==='native'&&!fallback&&!ay){fallback=true;audio.src='/api/stream/'+t.id;audio.play().catch(()=>{if(active&&queue[current]===t)skipBad(s)});status('Декодирование на сервере');return}skipBad(s)}
function skipBad(s:string){message((queue[current]?.name??'')+': '+s);failed.add(current);if(failed.size>=queue.length){stopPlayback();updateNow();return}advance(true,true)}
function advance(auto=false,skip=false){if(!queue.length)return;if(auto&&!skip&&repeat==='one'){playAt(current,false);return}let i=current;
 for(let j=0;j<queue.length;j++){if(shuffle){if(!bag.length){if(auto&&repeat==='off'&&history.length>=queue.length-1){stopPlayback();updateNow();return}bag=queue.map((_,k)=>k).filter(k=>k!==current)}if(!bag.length)i=0;else{const k=Math.floor(Math.random()*bag.length);i=bag[k];bag[k]=bag[bag.length-1];bag.pop()}}else{i++;if(i>=queue.length){if(auto&&repeat==='off'&&!skip){stopPlayback();updateNow();return}i=0}}if(!failed.has(i)){void playAt(i);return}}stopPlayback();updateNow()}
function add(ts:Track[]){if(!ts.length)return;queueChanged=true;const known=new Set(queue.map(t=>t.id));for(const t of ts)if(!known.has(t.id)){queue.push(t);known.add(t.id)}bag=[];history=[];failed.clear();if(selected<0)selected=0;renderQueue();updateNow()}
const selectedTrackIDs=new Set<string>();let selectionAnchor='';
let libraryView:'all'|'likes'|'recent'='all';
let folderPath='',folderPage=0;
type FolderNode={path:string,name:string,parent:string,counts:Record<string,number>};
let folderIndex=new Map<string,FolderNode>();
let folderChildren=new Map<string,FolderNode[]>();const expandedFolders=new Set<string>(),folderLimits=new Map<string,number>();
function sourceCount(n:FolderNode){return n.counts[select('source').value]??0}
function indexFolders(){folderIndex=new Map();folderChildren=new Map();for(const t of library){const parts=t.path.split('/');parts.pop();let parent='';for(const name of parts){const path=parent?parent+'/'+name:name;let n=folderIndex.get(path);if(!n){n={path,name,parent,counts:{all:0}};folderIndex.set(path,n)}n.counts.all++;n.counts[t.source]=(n.counts[t.source]??0)+1;parent=path}}for(const n of folderIndex.values()){const children=folderChildren.get(n.parent)??[];children.push(n);folderChildren.set(n.parent,children)}for(const children of folderChildren.values())children.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'}));}
function validFolder(){while(folderPath&&(!folderIndex.has(folderPath)||!sourceCount(folderIndex.get(folderPath)!)))folderPath=folderPath.includes('/')?folderPath.slice(0,folderPath.lastIndexOf('/')):''}
function browseLibraryFolder(path:string){folderPath=path;for(const p of ancestors(path))expandedFolders.add(p);folderPage=0;input('folderSearch').value='';renderLibrary()}
function renderFolderNav(){validFolder();const crumbs=el('folderCrumbs'),root=action('Все каталоги',()=>browseLibraryFolder(''));crumbs.replaceChildren(root);if(!folderPath)root.setAttribute('aria-current','page');let prefix='';for(const part of folderPath.split('/').filter(Boolean)){prefix=prefix?prefix+'/'+part:part;const dest=prefix;const sep=document.createElement('span');sep.textContent=' / ';const b=action(part,()=>browseLibraryFolder(dest));b.title=dest;if(dest===folderPath)b.setAttribute('aria-current','page');crumbs.append(sep,b)}btn('folderUp').disabled=!folderPath;

 const q=input('folderSearch').value.trim().toLocaleLowerCase(),grid=el('folderGrid');grid.replaceChildren();
 const make=(n:FolderNode,depth:number,search=false)=>{
  const line=document.createElement('div');line.className='folder-tree-line';line.style.setProperty('--depth',String(Math.min(depth,12)));
  const children=(folderChildren.get(n.path)??[]).filter(sourceCount);
  if(!search&&children.length){const toggle=action(expandedFolders.has(n.path)?'⌄':'›',()=>{if(expandedFolders.has(n.path))expandedFolders.delete(n.path);else expandedFolders.add(n.path);renderFolderNav()});toggle.className='folder-toggle';toggle.setAttribute('aria-expanded',String(expandedFolders.has(n.path)));toggle.setAttribute('aria-label','Подпапки '+n.name);line.append(toggle)}else{const space=document.createElement('span');space.className='folder-toggle-space';line.append(space)}
  const b=action('',()=>browseLibraryFolder(n.path));b.className='library-folder';b.title=n.path;if(n.path===folderPath)b.setAttribute('aria-current','page');
  const icon=document.createElement('span');icon.className='folder-glyph';icon.setAttribute('aria-hidden','true');const label=document.createElement('span');label.className='folder-label';label.textContent=search?n.path:n.name;const count=document.createElement('small');count.textContent=String(sourceCount(n));b.append(icon,label,count);line.append(b);grid.append(line);
 };
 const all=action('Вся коллекция',()=>browseLibraryFolder(''));all.className='folder-root';if(!folderPath)all.setAttribute('aria-current','page');grid.append(all);
 if(q){const nodes=[...folderIndex.values()].filter(n=>sourceCount(n)>0&&n.path.toLocaleLowerCase().includes(q)).sort((a,b)=>a.path.localeCompare(b.path,undefined,{numeric:true,sensitivity:'base'}));const pages=Math.max(1,Math.ceil(nodes.length/24));folderPage=Math.max(0,Math.min(pages-1,folderPage));for(const n of nodes.slice(folderPage*24,(folderPage+1)*24))make(n,0,true);if(!nodes.length)grid.append('Папки не найдены');el('folderPages').hidden=pages===1;el('folderPageInfo').textContent=(folderPage+1)+' / '+pages;btn('folderPrev').disabled=folderPage===0;btn('folderNext').disabled=folderPage>=pages-1;return}
 el('folderPages').hidden=true;
 const appendChildren=(parent:string,depth:number)=>{const nodes=(folderChildren.get(parent)??[]).filter(sourceCount),limit=folderLimits.get(parent)??48;for(const n of nodes.slice(0,limit)){make(n,depth);if(expandedFolders.has(n.path))appendChildren(n.path,depth+1)}if(nodes.length>limit){const more=action('Ещё '+(nodes.length-limit)+'…',()=>{folderLimits.set(parent,limit+48);renderFolderNav()});more.className='folder-more';more.style.setProperty('--depth',String(Math.min(depth,12)));grid.append(more)}};
 appendChildren('',0);
 if(!folderIndex.size)grid.append('Нет каталогов')
}
function filtered(){return filterLibrary(library,{query:input('search').value,source:select('source').value,folder:folderPath,recursive:input('folderRecursive').checked,format:select('libraryFormat').value,sort:select('librarySort').value,ids:libraryView==='all'?undefined:libraryView==='likes'?taste.likes:taste.recent})}
function row(t:Track,i:number,forQueue:boolean,selectable=false){const r=document.createElement('div');r.className='track'+(forQueue&&i===selected?' selected':'')+(forQueue&&i===current?' current':'');r.tabIndex=0;const info=document.createElement('div');info.className='info';const title=document.createElement('strong');title.textContent=(forQueue?String(i+1).padStart(2,'0')+'  ':'')+t.name;const sub=document.createElement('small');sub.textContent=t.source==='local'?'Локальный файл':identity.role==='admin'?(t.source==='uploads'?'Загрузки':'Сервер')+' / '+t.path:t.path;info.append(title);if(!forQueue)info.append(sub);else r.title=sub.textContent;const ext=document.createElement('span');ext.className='ext';ext.textContent=t.format.toUpperCase();const b=document.createElement('button');b.textContent='▶';b.title='Играть';b.onclick=e=>{e.stopPropagation();if(forQueue){failed.clear();void playAt(i)}else{add([t]);failed.clear();void playAt(queue.findIndex(x=>x.id===t.id))}};const open=()=>{if(!forQueue)add([t]);failed.clear();void playAt(forQueue?i:queue.findIndex(x=>x.id===t.id))};if(selectable){const check=document.createElement('input');check.type='checkbox';check.className='track-select';check.dataset.id=t.id;check.checked=selectedTrackIDs.has(t.id);check.setAttribute('aria-label','Выбрать '+t.name);check.onclick=e=>{e.stopPropagation();const list=filtered(),start=list.findIndex(x=>x.id===selectionAnchor),end=list.findIndex(x=>x.id===t.id);if(e.shiftKey&&start>=0&&end>=0){for(const x of list.slice(Math.min(start,end),Math.max(start,end)+1))check.checked?selectedTrackIDs.add(x.id):selectedTrackIDs.delete(x.id)}else check.checked?selectedTrackIDs.add(t.id):selectedTrackIDs.delete(t.id);selectionAnchor=t.id;updateSelection()};r.append(check)}r.append(info,ext);if(!forQueue)r.append(b);if(!t.file){const rating=makeRating(t,true);const negative=makeRating(t,false);r.append(rating,negative)}if(!forQueue){const plus=document.createElement('button');plus.textContent='+';plus.title='В очередь';plus.onclick=e=>{e.stopPropagation();add([t])};r.append(plus)}r.onclick=()=>{if(forQueue){selected=i;for(const node of Array.from(el('queue').querySelectorAll<HTMLElement>('[data-index]')))node.classList.toggle('selected',Number(node.dataset.index)===i);scheduleQueueSave();if(matchMedia('(pointer:coarse)').matches)open()}};r.ondblclick=e=>{if(!(e.target as HTMLElement).closest('button,input'))open()};r.onkeydown=e=>{if(e.key==='Enter'&&e.target===r)open()};return r}
function renderLibrary(){renderFolderNav();const ts=filtered(),l=el('library');l.scrollTop=0;el('libcount').textContent=ts.length+' / '+library.length;el('folderSummary').textContent=ts.length+' треков в выборке';btn('addAll').disabled=btn('playSelection').disabled=!ts.length;libraryRows.set(ts.length,i=>row(ts[i],i,false,true));if(!ts.length){const e=document.createElement('p');e.className='empty';e.textContent=libraryView==='likes'?'Здесь появятся понравившиеся композиции.':libraryView==='recent'?'Здесь появятся недавно прослушанные композиции.':library.length?'Ничего не найдено. Попробуйте изменить фильтры.':identity.role==='admin'?'Библиотека пуста. Добавьте музыку в разделе управления.':'В библиотеке пока нет музыки.';l.append(e)}updateSelection(ts);}
const queueRows=new VirtualRows(el('queue'),44);
const libraryRows=new VirtualRows(el('library'),64);
let queueSaveTimer:number|undefined,queueRestored=false,queueChanged=false;
function scheduleQueueSave(){if(!queueRestored){queueChanged=true;return}window.clearTimeout(queueSaveTimer);queueSaveTimer=window.setTimeout(saveQueue,300)}
function saveQueue(){if(!queueRestored)return;try{const ids=queue.filter(t=>!t.file).map(t=>t.id);localStorage.setItem('runeamp-queue-v1',JSON.stringify({ids,selected:queue[selected]?.id,current:queue[current]?.id}))}catch{message('Не удалось сохранить очередь в браузере')}}
function restoreQueue(){if(queueRestored)return;queueRestored=true;if(queueChanged){scheduleQueueSave();return}try{const state=JSON.parse(localStorage.getItem('runeamp-queue-v1')??'null');if(!state||!Array.isArray(state.ids))return;const byId=new Map(library.map(t=>[t.id,t]));queue=state.ids.flatMap((id:unknown)=>typeof id==='string'&&byId.has(id)?[byId.get(id)!]:[]);current=queue.findIndex(t=>t.id===state.current);selected=queue.findIndex(t=>t.id===state.selected);if(selected<0)selected=current>=0?current:queue.length?0:-1;renderQueue();updateNow()}catch{message('Не удалось восстановить очередь')}}
window.addEventListener('pagehide',saveQueue);
function renderQueue(){const l=el('queue');queueRows.set(queue.length,i=>row(queue[i],i,true));el('playlistcount').textContent=String(queue.length);el('wszCount').textContent=queue.length+' треков';requestAnimationFrame(renderFrame);if(!queue.length){const e=document.createElement('p');e.className='empty';e.textContent='Добавьте музыку из библиотеки или LOCAL.';l.append(e)}if(queueRestored)scheduleQueueSave()}
function setLibrary(ts:Track[]){library=ts;const fmt=select('libraryFormat'),old=fmt.value;fmt.replaceChildren(new Option('Все форматы','all'),...[...new Set(ts.map(t=>t.format))].sort().map(f=>new Option(f==='ts'?'TurboSound':f.toUpperCase(),f)));if([...Array.from(fmt.options)].some(o=>o.value===old))fmt.value=old;const ids=new Set(ts.map(t=>t.id));for(const id of selectedTrackIDs)if(!ids.has(id))selectedTrackIDs.delete(id);indexFolders();validFolder();renderLibrary();restoreQueue();if(location.pathname==='/playlists')syncPlaylistRoute()}
async function fetchLibrary(scan=false){try{setLibrary(await api<Track[]>(scan?'rescan':'library',scan?'POST':'GET'));message('В библиотеке: '+library.length+' композиций');if(location.pathname==='/admin'&&identity.role==='admin'){await browseFolder()}}catch(e){message(String(e))}}
async function fetchSaved(){try{const id=identity;const pub=await api<Playlist[]>('playlists');const personal=id.role==='guest'?[]:await api<Playlist[]>('personal-playlists');if(id!==identity)return;saved=[...pub.map(p=>({...p,scope:'public' as const})),...personal.map(p=>({...p,scope:'personal' as const}))];renderLists();syncPlaylistRoute()}catch(e){message(String(e))}}
function remove(){if(selected<0||selected>=queue.length)return;const i=selected;if(i===current){stopPlayback();current=-1}else if(i<current)current--;queue.splice(i,1);selected=Math.min(i,queue.length-1);bag=[];history=[];failed.clear();renderQueue();updateNow()}
function move(d:number){const j=selected+d;if(selected<0||j<0||j>=queue.length)return;const i=selected;[queue[i],queue[j]]=[queue[j],queue[i]];if(current===i)current=j;else if(current===j)current=i;selected=j;bag=[];history=[];renderQueue()}
function localFiles(files:File[]){const tracks:Track[]=[];for(const f of files){const ext=f.name.split('.').at(-1)?.toLowerCase()??'',ay=formatOf(f.name);if((ay&&f.size>=16&&f.size<=maxAYSize(ay))||['mp3','flac','wav','ogg','opus','m4a','aac'].includes(ext)){tracks.push({id:'local:'+f.name+':'+f.size+':'+f.lastModified,name:f.name,path:f.name,source:'local',format:ext,size:f.size,mode:ay?'ay':'native',file:f})}}add(tracks);message('Локально добавлено: '+tracks.length+'; файлы не отправлены на сервер')}
type ZipReport={path:string,tracks:number,archives:number,duplicates:number,skipped:number,bytes:number,badArchives?:number,badFiles?:number,warnings?:string[]};
function uploadWithProgress<T>(file:File,dir:string,label:string,source:string,archive:boolean):Promise<T>{return new Promise((resolve,reject)=>{const request=new XMLHttpRequest(),progress=el<HTMLProgressElement>('uploadProgress');request.open('POST','/api/'+(archive?'import-zip':'upload')+'?source='+encodeURIComponent(source)+'&dir='+encodeURIComponent(dir));request.setRequestHeader('X-RuneAmp-Request','1');request.upload.onprogress=e=>{if(e.lengthComputable){progress.value=e.loaded/e.total*100;el('uploadStatus').textContent=label+' · '+Math.round(progress.value)+'%'}};request.upload.onload=()=>{progress.removeAttribute('value');el('uploadStatus').textContent=label+(archive?' · распаковка и индексация…':' · сохранение и индексация…')};request.onload=()=>{try{const data=JSON.parse(request.responseText);if(request.status<200||request.status>=300)throw Error(data.error??'HTTP '+request.status);resolve(data as T)}catch(e){reject(e)}};request.onerror=()=>reject(Error('Ошибка соединения'));request.onabort=()=>reject(Error('Загрузка прервана'));const form=new FormData();form.append('file',file);request.send(form)})}
async function upload(files:File[]){if(identity.role!=='admin'||!files.length||!writable||fileBusy||btn('upload').disabled)return;fileBusy=true;updateFileTools();btn('upload').disabled=btn('rescan').disabled=true;const dir=adminDir,source=select('browseSource').value;let count=0,archives=0,duplicates=0,skipped=0,badArchives=0,badFiles=0;const problems:string[]=[],warnings:string[]=[];const progress=el<HTMLProgressElement>('uploadProgress');progress.hidden=false;try{for(const [i,f] of files.entries()){if(identity.role!=='admin')break;const label='Загрузка '+(i+1)+' / '+files.length+' · '+f.name;el('uploadStatus').textContent=label;progress.value=0;try{if(/\.zip$/i.test(f.name)){const report=await uploadWithProgress<ZipReport>(f,dir,label,source,true);count+=report.tracks;archives+=report.archives;duplicates+=report.duplicates;skipped+=report.skipped;badArchives+=report.badArchives??0;badFiles+=report.badFiles??0;for(const warning of report.warnings??[]){if(warnings.length<10)warnings.push(warning)}}else{await uploadWithProgress<Track>(f,dir,label,source,false);count++}}catch(e){problems.push(f.name+': '+String(e))}}const summary='Загружено: '+count+' треков'+(archives?' · ZIP обработано: '+archives+' · дубликатов: '+duplicates+' · пропущено: '+skipped:'')+(badArchives||badFiles?' · битых/неподдерживаемых ZIP: '+badArchives+' · повреждённых файлов: '+badFiles:'')+(warnings.length?' · '+warnings.join('; '):'')+(problems.length?' · '+problems.join('; '):'');el('uploadStatus').textContent='Обновление библиотеки…';try{setLibrary(await api<Track[]>('rescan','POST'));await browseFolder();el('uploadStatus').textContent=summary+' · библиотека обновлена'}catch(e){el('uploadStatus').textContent=summary+' · ошибка пересканирования: '+String(e)}}finally{progress.hidden=true;fileBusy=false;btn('rescan').disabled=false;renderAdminEntries()}}

