type Taste={likes:string[],dislikes:string[],recent:string[],weights:Record<string,number>};
let taste:Taste={likes:[],dislikes:[],recent:[],weights:{}},listeningStarted=false;
function tasteKey(){return 'runeamp-taste-v1-'+(identity.role==='guest'?'guest':identity.role+':'+identity.name)}
function readTaste(){taste={likes:[],dislikes:[],recent:[],weights:{}};try{const p=JSON.parse(localStorage.getItem(tasteKey())??'{}');for(const k of ['likes','dislikes','recent'] as const)if(Array.isArray(p[k]))taste[k]=p[k].filter((x:unknown)=>typeof x==='string').slice(0,1000);if(p.weights&&typeof p.weights==='object')for(const [k,v] of Object.entries(p.weights).slice(0,2000))if(typeof v==='number'&&Number.isFinite(v))taste.weights[k]=Math.max(-10,Math.min(10,v))}catch{}updateLike()}
function writeTaste(){try{localStorage.setItem(tasteKey(),JSON.stringify(taste))}catch{}}
function tasteKeys(t:Track){return ['mode:'+t.mode,'format:'+t.format,'folder:'+t.source+':'+t.path.split('/').slice(0,-1).join('/')]}
function adjust(t:Track,delta:number){for(const k of tasteKeys(t))taste.weights[k]=Math.max(-10,Math.min(10,(taste.weights[k]??0)+delta));writeTaste()}
function noteRecent(t:Track){if(t.file)return;taste.recent=[t.id,...taste.recent.filter(x=>x!==t.id)].slice(0,100);writeTaste()}
function recordListening(ended:boolean){if(!listeningStarted)return;listeningStarted=false;const t=queue[current];if(!t||t.file||!active)return;const seconds=ay?.seconds??audio.currentTime;if(ended||seconds>=30)adjust(t,1);else if(seconds>=1&&seconds<8&&!paused)adjust(t,-.2)}
function paintRating(b:HTMLButtonElement,t:Track|undefined,positive:boolean,full=false){const on=!!t&&(positive?taste.likes:taste.dislikes).includes(t.id);b.disabled=!t||!!t.file;const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('width','14');svg.setAttribute('height','14');svg.setAttribute('aria-hidden','true');svg.setAttribute('fill',on?'currentColor':'none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.8');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('stroke-linecap','round');const path=document.createElementNS(ns,'path');path.setAttribute('d',positive?'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z':'M17 14V3M7 3h10l4 1v9l-4 1h-4l1 5a2 2 0 0 1-2 2l-6-8V5a2 2 0 0 1 1-2Z');svg.append(path);b.replaceChildren(svg);if(full)b.append(positive?' Нравится':' Не нравится');b.title=positive?(on?'Убрать из избранного':'Нравится · добавить в избранное'):(on?'Отменить отметку':'Не нравится');b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(on));b.classList.toggle('positive',positive);b.classList.toggle('negative',!positive)}
function updateLike(){const t=queue[current];for(const id of ['like','miniLike','dislike','miniDislike'])paintRating(btn(id),t,id==='like'||id==='miniLike',id==='like'||id==='dislike');const byId=new Map([...library,...queue].map(t=>[t.id,t]));document.querySelectorAll<HTMLButtonElement>('button[data-rating]').forEach(b=>paintRating(b,byId.get(b.dataset.track??''),b.dataset.rating==='like'))}
function rate(t:Track|undefined,positive:boolean){if(!t||t.file)return;const wasLike=taste.likes.includes(t.id),wasDislike=taste.dislikes.includes(t.id);taste.likes=taste.likes.filter(x=>x!==t.id);taste.dislikes=taste.dislikes.filter(x=>x!==t.id);if(positive&&!wasLike)taste.likes.unshift(t.id);if(!positive&&!wasDislike)taste.dislikes.unshift(t.id);taste.likes=taste.likes.slice(0,1000);taste.dislikes=taste.dislikes.slice(0,1000);adjust(t,(taste.likes.includes(t.id)?3:taste.dislikes.includes(t.id)?-4:0)-(wasLike?3:wasDislike?-4:0));writeTaste();updateLike();if(libraryView==='likes')renderLibrary();message(positive?(wasLike?'Убрано из избранного':'Добавлено в избранное'):(wasDislike?'Отметка снята':'Исключено из персонального радио'))}
