function like(){rate(queue[current],true)}
function startRadio(ts:Track[],random=true){if(!ts.length){message('В этой подборке пока нет музыки');return}stopPlayback();queueChanged=true;queue=ts.slice();current=-1;selected=0;bag=[];history=[];failed.clear();shuffle=random;repeat='all';input('shuffle').checked=shuffle;select('repeat').value=repeat;pref();renderQueue();updateNow();void playAt(random?Math.floor(Math.random()*queue.length):0)}
function personalized(){const pool=library.filter(t=>!taste.dislikes.includes(t.id));const ranked=pool.map(t=>{const affinity=tasteKeys(t).reduce((s,k)=>s+(taste.weights[k]??0),0);return {t,score:affinity+(taste.likes.includes(t.id)?5:0)-(taste.recent.slice(0,12).includes(t.id)?5:0)+Math.random()*5}}).sort((a,b)=>b.score-a.score);const chosen:Track[]=[];const unseen=pool.filter(t=>!taste.recent.includes(t.id));while(chosen.length<Math.min(50,pool.length)){let t:Track|undefined;if(chosen.length%5===4){const rest=unseen.filter(t=>!chosen.includes(t));t=rest[Math.floor(Math.random()*rest.length)]}if(!t)t=ranked.find(r=>!chosen.includes(r.t))?.t;if(!t)break;chosen.push(t)}startRadio(chosen,false)}
