const editorLibraryRows=new VirtualRows(el('editorLibrary'),64),editorTrackRows=new VirtualRows(el('editorTracks'),64);
function renderEditor(){const q=input('editorSearch').value.trim().toLowerCase(),a=el('editorLibrary'),b=el('editorTracks');const matches=library.filter(t=>(t.name+' '+t.path).toLowerCase().includes(q)),known=new Set(editorIDs);editorLibraryRows.set(matches.length,i=>{const t=matches[i],r=infoRow(t.name,t.path),addButton=action('+',()=>{if(!known.has(t.id)){editorIDs.push(t.id);renderEditor()}});addButton.disabled=known.has(t.id);r.append(addButton);return r});const byId=new Map(library.map(t=>[t.id,t]));editorTrackRows.set(editorIDs.length,i=>{const id=editorIDs[i],t=byId.get(id),r=infoRow((i+1)+'. '+(t?.name??'Недоступный трек'),t?.path??id);const move=(d:number)=>{const j=i+d;if(j<0||j>=editorIDs.length)return;[editorIDs[i],editorIDs[j]]=[editorIDs[j],editorIDs[i]];renderEditor()};r.append(action('↑',()=>move(-1)),action('↓',()=>move(1)),action('×',()=>{editorIDs.splice(i,1);renderEditor()}));return r});if(!matches.length)a.textContent='Ничего не найдено';if(!editorIDs.length)b.textContent='Добавьте треки из библиотеки';el('editorTitle').textContent='Редактор плейлиста · '+editorIDs.length+' треков'}
