function adminKey(source:string,p:string){return source+'\0'+p}
function currentAdminTracks(){return selectedFolderTracks(library,[...adminSelected.values()])}
function updateFileTools(){const source=select('browseSource').value;const can=writable&&!fileBusy&&identity.role==='admin';select('browseSource').disabled=fileBusy;btn('adminUp').disabled=fileBusy||adminDir==='.';btn('browseRefresh').disabled=fileBusy;for(const id of ['mkdir','upload'])btn(id).disabled=!can;el('dropHint').hidden=!can;btn('pasteEntries').hidden=!moveClipboard.length;btn('pasteEntries').disabled=!can||moveClipboard.some(x=>x.source!==source);btn('cancelMove').hidden=!moveClipboard.length;const n=adminSelected.size;el('adminBulk').hidden=!n;el('selectedEntries').textContent=n+' выбрано';btn('clearEntries').disabled=!n;const trackCount=currentAdminTracks().length;el('selectedEntries').textContent=n+' выбрано · '+trackCount+' треков';const hasTracks=trackCount>0;btn('sendEntries').disabled=!hasTracks||fileBusy;btn('queueEntries').disabled=!hasTracks||fileBusy;for(const id of ['cutEntries','deleteEntries'])btn(id).disabled=!can||!n||[...adminSelected.values()].some(x=>x.source!==source)}
function openAdminDir(dir:string){if(fileBusy)return;adminDir=dir;adminAnchor='';input('adminFileSearch').value='';void browseFolder()}
function visibleEntries(){const q=input('adminFileSearch').value.trim().toLowerCase(),sort=select('adminFileSort').value;return adminEntries.filter(e=>e.name.toLowerCase().includes(q)).sort((a,b)=>Number(b.directory)-Number(a.directory)||(sort==='size'?(b.size??0)-(a.size??0):sort==='type'?(a.format??'').localeCompare(b.format??''):0)||a.name.localeCompare(b.name,undefined,{numeric:true}))}
const adminFileRows=new VirtualRows(el('folderContents'),56);
function renderAdminEntries(){
 const source=select('browseSource').value,target=el('folderContents'),list=visibleEntries(),trackByPath=new Map(library.filter(t=>t.source===source).map(t=>[t.path,t])),can=writable&&!fileBusy;
 const up=adminDir!=='.'?1:0;
 adminFileRows.set(list.length+up,i=>{
  if(up&&i===0){const b=action('..  На уровень выше',()=>openAdminDir(parentDir(adminDir)));b.className='admin-parent';b.disabled=fileBusy;return b}
  const e=list[i-up],r=document.createElement('div');r.className='admin-file-row';const key=adminKey(source,e.path),check=document.createElement('input');check.type='checkbox';check.checked=adminSelected.has(key);check.disabled=fileBusy;check.setAttribute('aria-label','Выбрать '+e.name);r.classList.toggle('selected',check.checked);
  check.onclick=ev=>{const start=list.findIndex(x=>adminKey(source,x.path)===adminAnchor),end=i-up,group=ev.shiftKey&&start>=0?list.slice(Math.min(start,end),Math.max(start,end)+1):[e];for(const entry of group){const k=adminKey(source,entry.path);if(check.checked)adminSelected.set(k,{source,entry});else adminSelected.delete(k)}adminAnchor=key;if(group.length>1)renderAdminEntries();else{r.classList.toggle('selected',check.checked);updateFileTools();updateAdminCheck()}};
  const name=document.createElement('div');name.className='admin-file-name';const icon=document.createElement('span');icon.className=e.directory?'folder-glyph':'admin-music-glyph';icon.textContent=e.directory?'':e.music?'♫':'◇';icon.setAttribute('aria-hidden','true');const t=trackByPath.get(e.path),open=()=>{if(fileBusy)return;if(e.directory)openAdminDir(e.path);else if(t){add([t]);void playAt(queue.findIndex(x=>x.id===t.id))}};
  const title=action(e.name,open);title.className='admin-filename';title.disabled=fileBusy||(!e.directory&&!t);title.title=e.path;name.append(icon,title);
  const type=document.createElement('span');type.className='admin-file-type';type.textContent=e.directory?'Папка':e.music?(e.format??'').toUpperCase():'Файл';
  const size=document.createElement('span');size.className='admin-file-size';size.textContent=e.directory?'—':(e.size??0)>=1048576?((e.size??0)/1048576).toFixed(1)+' МиБ':Math.round((e.size??0)/1024)+' КиБ';
  const tools=document.createElement('div');tools.className='admin-file-actions';
  if(t){const play=action('▶',open);play.title='Слушать';play.disabled=fileBusy;tools.append(play)}
  const more=action('⋯',()=>showServiceActions(e.name,[
   ...(e.directory?[{label:'Открыть папку',run:open,disabled:fileBusy}]:t?[{label:'Воспроизвести',run:open,disabled:fileBusy}]:[]),
   {label:'В очередь',run:()=>add(selectedFolderTracks(library,[{source,entry:e}])),disabled:fileBusy||(!e.directory&&!e.indexed)},
   {label:'В плейлист',run:()=>void openAppend(selectedFolderTracks(library,[{source,entry:e}]).map(x=>x.id)),disabled:fileBusy||(!e.directory&&!e.indexed)},
   {label:'Переименовать',run:()=>void renameEntry(source,e),disabled:!can},
   {label:'Переместить',run:()=>{moveClipboard=[{source,entry:e}];updateFileTools();el('deleteStatus').textContent='Откройте папку назначения и нажмите «Переместить сюда»'},disabled:!can},
   {label:'Удалить',run:()=>void deleteMusic(source,e),disabled:!can,danger:true}
  ]));more.setAttribute('aria-label','Действия: '+e.name);more.disabled=fileBusy;tools.append(more);r.append(check,name,type,size,tools);
  r.ondblclick=ev=>{if(!(ev.target as HTMLElement).closest('button,input'))open()};return r;
 });
 if(!list.length&&!up)target.textContent='Нет файлов и папок.';updateAdminCheck();updateFileTools();
}
function updateAdminCheck(){const src=select('browseSource').value,list=visibleEntries(),n=list.filter(e=>adminSelected.has(adminKey(src,e.path))).length;input('selectEntries').checked=!!list.length&&n===list.length;input('selectEntries').indeterminate=n>0&&n<list.length}
function parentDir(p:string){return p.includes('/')?p.slice(0,p.lastIndexOf('/')):'.'}
function joinDir(dir:string,name:string){return dir==='.'?name:dir+'/'+name}
async function browseFolder(){if(identity.role!=='admin')return;const g=++browseGeneration,source=select('browseSource').value,dir=adminDir,target=el('folderContents');target.scrollTop=0;target.textContent='Чтение папки…';try{const data=await api<{entries:FolderEntry[],tracks:number,folders:number,truncated:boolean,writable:boolean}>('admin/folder?source='+encodeURIComponent(source)+'&dir='+encodeURIComponent(dir));if(g!==browseGeneration||identity.role!=='admin')return;writable=data.writable;adminEntries=data.entries;el('writeMode').textContent=writable?'Операции выполняются в открытой папке.':'Хранилище только для чтения.';el('folderCount').textContent=data.tracks+' треков · '+data.folders+' папок'+(data.truncated?' · ограниченный список':'');const nav=el('adminCrumbs');nav.replaceChildren(action('Корень',()=>openAdminDir('.')));let prefix='.';for(const part of dir==='.'?[]:dir.split('/')){prefix=joinDir(prefix,part);const p=prefix;nav.append(' / ',action(part,()=>openAdminDir(p)))}btn('adminUp').disabled=dir==='.';renderAdminEntries()}catch(e){if(g===browseGeneration){target.textContent=String(e);adminEntries=[];writable=false;updateFileTools()}}}
async function refreshFiles(){setLibrary(await api<Track[]>('library'));const byId=new Map(library.map(t=>[t.id,t]));const playing=queue[current],sel=queue[selected];if(playing&&!playing.file&&!byId.has(playing.id))stopPlayback();queue=queue.flatMap(t=>t.file?[t]:byId.has(t.id)?[byId.get(t.id)!]:[]);current=playing?queue.findIndex(t=>t.id===playing.id):-1;selected=sel?queue.findIndex(t=>t.id===sel.id):-1;bag=[];history=[];failed.clear();renderQueue();updateNow();await browseFolder()}
async function runFileOps(items:{source:string,entry:FolderEntry}[],moveTo?:string){if(fileBusy||identity.role!=='admin')return;fileBusy=true;updateFileTools();let done=0;const errors:string[]=[];const unique=items.filter(x=>!items.some(y=>y!==x&&y.source===x.source&&y.entry.directory&&x.entry.path.startsWith(y.entry.path+'/')));try{for(const x of unique){if(identity.role!=='admin')break;try{if(moveTo!==undefined)await api('admin/move','POST',JSON.stringify({source:x.source,path:x.entry.path,destination:joinDir(moveTo,x.entry.name)}));else await api('admin/entry','DELETE',JSON.stringify({source:x.source,path:x.entry.path,directory:x.entry.directory}));done++;for(const [key,v] of adminSelected)if(v.source===x.source&&(v.entry.path===x.entry.path||v.entry.path.startsWith(x.entry.path+'/')))adminSelected.delete(key);if(moveTo!==undefined)moveClipboard=moveClipboard.filter(v=>v.source!==x.source||!(v.entry.path===x.entry.path||x.entry.directory&&v.entry.path.startsWith(x.entry.path+'/')))}catch(e){errors.push(x.entry.name+': '+String(e))}}await refreshFiles();el('deleteStatus').textContent=(moveTo!==undefined?'Перемещено: ':'Удалено: ')+done+(errors.length?' · '+errors.join('; '):'')}catch(e){el('deleteStatus').textContent='Выполнено: '+done+' · ошибка обновления: '+String(e)}finally{fileBusy=false;updateFileTools();renderAdminEntries()}}
async function deleteMusic(source:string,e:FolderEntry){if(!confirm('Удалить без восстановления: '+e.path+(e.directory?' и всё содержимое?':'?')))return;await runFileOps([{source,entry:e}])}
async function renameEntry(source:string,e:FolderEntry){const name=prompt('Новое имя',e.name)?.trim();if(!name||name===e.name||name.includes('/')||fileBusy)return;fileBusy=true;updateFileTools();try{await api('admin/move','POST',JSON.stringify({source,path:e.path,destination:joinDir(parentDir(e.path),name)}));adminSelected.clear();await refreshFiles();el('deleteStatus').textContent='Переименовано: '+name}catch(err){el('deleteStatus').textContent=String(err)}finally{fileBusy=false;renderAdminEntries()}}
