const localSkinGroup=document.createElement('optgroup');localSkinGroup.label='Локальные';const serverSkinGroup=document.createElement('optgroup');serverSkinGroup.label='Серверные';const builtinGroup=document.createElement('optgroup');builtinGroup.label='Встроенные';const skinSelect=select('skin');for(const o of Array.from(skinSelect.options))builtinGroup.append(o);skinSelect.append(builtinGroup,serverSkinGroup,localSkinGroup);
let serverSkins:ServerSkin[]=[],skinGeneration=0,adminSkinGeneration=0,skinPage=0;
async function refreshServerSkins(){try{serverSkins=await api<ServerSkin[]>('skins');serverSkinGroup.replaceChildren(...serverSkins.map(s=>new Option(s.name,'server:'+s.id)));if(Array.from(skinSelect.options).some(o=>o.value===skin))skinSelect.value=skin}catch(e){message(String(e))}}
async function skinFile(s:ServerSkin,admin=false){const response=await fetch('/api/'+(admin?'admin/':'')+'skins/'+encodeURIComponent(s.id));if(!response.ok)throw Error('Скин недоступен');return new File([await response.blob()],s.name+'.wsz')}
async function chooseSkin(value:string){const g=++skinGeneration;try{if(value.startsWith('server:')){const info=serverSkins.find(s=>'server:'+s.id===value);if(!info)throw Error('Скин недоступен');if(!imported.has(value)){const file=await skinFile(info);const decoded=await decodeSkin(file);if(g!==skinGeneration){disposeSkin(decoded);return}for(const [id,old] of imported)if(id.startsWith('server:')){disposeSkin(old.skin);imported.delete(id)}imported.set(value,{file,skin:decoded})}}else if(!skinNames.includes(value)&&!imported.has(value))value='silver';if(g!==skinGeneration)return;skin=value;applySkin()}catch(e){if(g===skinGeneration){skin='silver';applySkin();message(String(e))}}}
async function loadAdminSkins(){if(identity.role!=='admin')return;const g=++adminSkinGeneration;const grid=el('serverSkinGrid');grid.textContent='Загрузка…';try{const fetched=await api<ServerSkin[]>('admin/skins');if(g!==adminSkinGeneration||identity.role!=='admin')return;const q=input('adminSkinSearch').value.trim().toLocaleLowerCase(),filter=select('adminSkinFilter').value,all=fetched.filter(s=>(!q||s.name.toLocaleLowerCase().includes(q))&&(filter==='all'||filter==='visible'&&s.visible||filter==='hidden'&&!s.visible||filter==='default'&&s.default));const pages=Math.max(1,Math.ceil(all.length/12));skinPage=Math.min(skinPage,pages-1);grid.replaceChildren();for(const s of all.slice(skinPage*12,(skinPage+1)*12)){const card=document.createElement('div');card.className='server-skin-card'+(s.default?' default-skin':'');const canvas=document.createElement('canvas');canvas.width=275;canvas.height=116;canvas.setAttribute('aria-label',s.name);const title=document.createElement('strong');title.textContent=s.name;const meta=document.createElement('small');meta.textContent=Math.round(s.size/1024)+' КиБ · '+(s.visible?'Общедоступный':'Скрытый')+(s.default?' · По умолчанию':'');const tools=document.createElement('div');tools.className='tools';tools.append(action('⋯ Действия',()=>showServiceActions(s.name,[{label:s.visible?'Скрыть':'Показать',run:()=>void changeServerSkin(s,{visible:!s.visible,default:false})},{label:s.default?'Снять умолчание':'По умолчанию',run:()=>void changeServerSkin(s,{visible:true,default:!s.default})},{label:'Удалить',danger:true,run:()=>{if(confirm('Удалить скин «'+s.name+'»?'))void changeServerSkin(s)}}])));card.append(canvas,title,meta,tools);grid.append(card);void (async()=>{try{const decoded=await decodeSkin(await skinFile(s,true));try{if(g===adminSkinGeneration&&identity.role==='admin')drawSkin(canvas,decoded,{name:'RuneAmp',time:'02:36',playing:false,paused:false,volume:.65,position:.3,seekable:true,shuffle:false,repeat:'off',playlist:true})}finally{disposeSkin(decoded)}}catch{canvas.title='Не удалось построить предпросмотр'}})()}
 if(!all.length)grid.textContent=fetched.length?'Скины не найдены.':'Нет загруженных скинов.';const nav=document.createElement('div');nav.className='tools';const prev=action('←',()=>{skinPage--;void loadAdminSkins()}),next=action('→',()=>{skinPage++;void loadAdminSkins()});prev.disabled=skinPage===0;next.disabled=skinPage>=pages-1;nav.append(prev,(skinPage+1)+' / '+pages+' · '+all.length,next);grid.append(nav)
 }catch(e){grid.textContent=String(e)}}
async function changeServerSkin(s:ServerSkin,patch?:{visible:boolean,default:boolean}){if(identity.role!=='admin')return;try{await api('admin/skins/'+s.id,patch?'PUT':'DELETE',patch?JSON.stringify(patch):undefined);await refreshServerSkins();if(skin.startsWith('server:')&&!serverSkins.some(s=>'server:'+s.id===skin))await chooseSkin('silver');await loadAdminSkins()}catch(e){el('serverSkinStatus').textContent=String(e)}}
