input('serverSkinFiles').onchange=async()=>{if(identity.role!=='admin')return;const files=Array.from(input('serverSkinFiles').files??[]);input('serverSkinFiles').value='';btn('serverSkinUpload').disabled=true;let count=0;const errors:string[]=[];try{for(const file of files){if(identity.role!=='admin')break;el('serverSkinStatus').textContent='Загрузка '+file.name;try{const decoded=await decodeSkin(file);disposeSkin(decoded);const form=new FormData();form.append('file',file);await api('admin/skins','POST',form);count++}catch(e){errors.push(file.name+': '+String(e))}}el('serverSkinStatus').textContent='Загружено: '+count+(errors.length?' · '+errors.join('; '):'');await refreshServerSkins();await loadAdminSkins()}finally{btn('serverSkinUpload').disabled=false}};
