function syncEQ(){const item=imported.get(skin),skinned=!!item&&hasEQFrame(item.skin);el('eqNative').hidden=skinned;el('eqSkin').hidden=!skinned;input('eqEnabled').checked=eq.enabled;btn('eqSkinOn').setAttribute('aria-pressed',String(eq.enabled));input('balance').value=String(eq.balance*100);input('wszBalance').value=String(eq.balance*100);el('balanceValue').textContent=eq.balance===0?'0':Math.round(Math.abs(eq.balance)*100)+(eq.balance<0?' L':' R');for(const [i,v] of [eq.preamp,...eq.bands].entries()){for(const slider of [eqInputs[i],eqSkinInputs[i]]){if(!slider)continue;slider.value=String(v);slider.title=(v>0?'+':'')+v+' dB';slider.setAttribute('aria-valuetext',v+' dB')}}if(skinned)drawEQ(el<HTMLCanvasElement>('eqCanvas'),item!.skin,eq)}
